{% set customer_doc = frappe.get_doc("Customer", doc.party_name) if doc.party_name and frappe.db.exists("Customer", doc.party_name) else None %}
{% set cust_mobile = doc.contact_mobile or doc.custom_mobile_no or (customer_doc.custom_mobile_no if customer_doc else "") or (customer_doc.mobile_no if customer_doc else "") %}
{% set cust_address = doc.address_display or (customer_doc.custom_address_text if customer_doc else "") or (customer_doc.primary_address if customer_doc else "") %}

{# Split items into Labor (Services / is_stock_item=0) and Parts & Materials (Inventory / is_stock_item=1) #}
{% set labor_items = [] %}
{% set parts_items = [] %}
{% set total_labor_amount = namespace(value=0.0) %}
{% set total_parts_amount = namespace(value=0.0) %}

{% for row in doc.items %}
    {% set is_stock = frappe.db.get_value("Item", row.item_code, "is_stock_item") %}
    {% if is_stock %}
        {% set _ = parts_items.append(row) %}
        {% set total_parts_amount.value = total_parts_amount.value + (row.amount or 0.0) %}
    {% else %}
        {% set _ = labor_items.append(row) %}
        {% set total_labor_amount.value = total_labor_amount.value + (row.amount or 0.0) %}
    {% endif %}
{% endfor %}

<div class="estimate-container">
  <!-- Header: Logo & Company on Left, Estimate Title & Meta on Right -->
  <table class="header-table">
    <tr>
      <td style="width: 50%;">
        <img src="/files/ultra_mrf_logo.png" style="max-height: 55px; max-width: 220px; object-fit: contain;" alt="ULTRA MRF" />
        <div class="company-title">{{ doc.company or "ULTRA MRF" }}</div>
      </td>
      <td style="width: 50%;" class="text-right">
        <div class="estimate-title">ESTIMATE</div>
        <div class="doc-meta">
          <div class="meta-id">{{ doc.name }}</div>
          <div>{{ frappe.utils.formatdate(doc.transaction_date, "MM/dd/yyyy") if doc.transaction_date else "" }}</div>
