          <td class="text-center">{{ loop.index }}</td>
          <td>{{ row.description or row.item_name or row.item_code }}</td>
          <td class="text-center">{{ (row.qty | int) if (row.qty % 1 == 0) else row.qty }}{{ row.uom or "" }}</td>
          <td class="text-right">{{ frappe.utils.fmt_money(row.rate, currency=doc.currency) }}</td>
          <td class="text-right">{{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}</td>
        </tr>
        {% endfor %}
        <tr class="total-row">
          <td colspan="4" class="text-right" style="padding-right: 15px;">Total</td>
          <td class="text-right">{{ frappe.utils.fmt_money(total_parts_amount.value, currency=doc.currency) }}</td>
        </tr>
      </tbody>
    </table>
  </div>
  {% endif %}

  <!-- REMARKS BOX -->
  <div class="remarks-box">
    <div class="remarks-header">REMARKS</div>
    <div class="remarks-body">
      {{ doc.remarks or doc.terms or "CASH PAYMENT ONLY" }}
    </div>
  </div>

  <!-- TOTALS SUMMARY SECTION -->
  <div style="width: 100%; overflow: hidden;">
    <table class="summary-table">
      <tr>
        <td class="summary-label">SUBTOTAL</td>
        <td class="summary-value">{{ frappe.utils.fmt_money(doc.total or (total_labor_amount.value + total_parts_amount.value), currency=doc.currency) }}</td>
      </tr>
      {% if doc.discount_amount and doc.discount_amount > 0 %}
      <tr>
        <td class="summary-label">DISCOUNT</td>
        <td class="summary-value">{{ frappe.utils.fmt_money(doc.discount_amount, currency=doc.currency) }}</td>
      </tr>
      {% endif %}
      <tr class="total-due-row">
        <td class="summary-label" style="font-size: 15px; font-weight: 900;">TOTAL AMOUNT DUE</td>
        <td class="summary-value" style="font-size: 15px; font-weight: 900;">{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td>
      </tr>
    </table>
  </div>

  <!-- SIGNATURES SECTION -->
  <table class="signature-section">
    <tr>
      <td style="width: 45%; text-align: center; vertical-align: bottom;">
        <div class="sig-title">ESTIMATED BY</div>
        <div class="sig-line">SIGNATURE OVER PRINTED NAME</div>
      </td>
      <td style="width: 10%;"></td>
      <td style="width: 45%; text-align: center; vertical-align: bottom;">
        <div class="sig-title">ACKNOWLEDGED BY</div>
        <div class="sig-line">SIGNATURE OVER PRINTED NAME</div>
      </td>
    </tr>
  </table>
</div>

