css:
@page {
  size: A4 portrait;
  margin: 12mm 15mm 15mm 15mm;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 8.5pt;
  color: #111;
  line-height: 1.35;
}

.estimate-container {
  width: 100%;
  max-width: 100%;
}

.header-table {
  width: 100%;
  margin-bottom: 12px;
  border-collapse: collapse;
}

.company-title {
  font-size: 9pt;
  font-weight: bold;
  color: #333;
  margin-top: 3px;
  letter-spacing: 0.5px;
}

.estimate-title {
  font-size: 16pt;
  font-weight: 900;
  color: #1a56db;
  letter-spacing: 1px;
}

.doc-meta {
  font-size: 8.5pt;
  color: #444;
  margin-top: 2px;
}

.meta-id {
  font-size: 11pt;
  font-weight: bold;
  color: #111;
  margin-bottom: 2px;
}

.info-table {
  width: 100%;
  border: 1px solid #d1d5db;
  border-radius: 4px;
  padding: 8px 10px;
  background-color: #f9fafb;
  margin-bottom: 12px;
  border-collapse: separate;
}

.inner-info-table {
  width: 100%;
  border-collapse: collapse;
}

.inner-info-table td {
  padding: 2px 4px;
  font-size: 8.5pt;
  vertical-align: top;
}

.info-label {
  width: 32%;
  color: #4b5563;
  font-weight: 500;
}

.info-val {
  width: 68%;
  color: #111;
}

.font-bold {
  font-weight: 700;
}

.section-title {
  font-size: 8.5pt;
  font-weight: 800;
  color: #1f2937;
  letter-spacing: 0.5px;
  margin-bottom: 4px;
  border-bottom: 1.5px solid #1a56db;
  padding-bottom: 2px;
}

.items-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 8px;
}

.items-table th {
  background-color: #f3f4f6;
  border-top: 1px solid #d1d5db;
  border-bottom: 1px solid #d1d5db;
  padding: 5px 6px;
  font-size: 8pt;
  font-weight: 700;
  color: #374151;
  text-transform: uppercase;
}

.items-table td {
  border-bottom: 1px solid #e5e7eb;
  padding: 5px 6px;
  font-size: 8.5pt;
  vertical-align: middle;
}

.items-table tfoot td {
  border-top: 1.5px solid #d1d5db;
  border-bottom: none;
  padding: 4px 6px;
  font-size: 8.5pt;
  background-color: #fafafa;
}

.item-name {
  font-weight: 600;
  color: #111;
}

.item-sub {
  font-size: 7.5pt;
  color: #6b7280;
  margin-top: 1px;
}

.totals-table {
  width: 42%;
  float: right;
  border-collapse: collapse;
  margin-top: 10px;
  margin-bottom: 15px;
}

.totals-table td {
  padding: 3px 6px;
  font-size: 8.5pt;
}

.totals-label {
  text-align: right;
  color: #4b5563;
  width: 55%;
}

.totals-val {
  text-align: right;
  font-weight: 600;
  width: 45%;
}

.grand-total-row td {
  background-color: #f9fafb;
}

.sig-table {
  width: 100%;
  margin-top: 35px;
  border-collapse: collapse;
}

.sig-line {
  border-top: 1px solid #4b5563;
  width: 85%;
  margin: 0 auto;
}

.sig-name {
  text-align: center;
  font-size: 8pt;
  font-weight: 600;
  color: #374151;
  margin-top: 4px;
}
